"use client"

import { useState } from "react"
import { motion, AnimatePresence } from "framer-motion"
import Link from "next/link"
import { Lock, Mail, Eye, EyeOff, ArrowLeft, Sparkles, User } from "lucide-react"
import { Button } from "@/components/ui/button"

export default function LoginPage() {
  const [isLogin, setIsLogin] = useState(true)
  const [showPassword, setShowPassword] = useState(false)
  const [showConfirmPassword, setShowConfirmPassword] = useState(false)
  const [email, setEmail] = useState("")
  const [password, setPassword] = useState("")
  const [confirmPassword, setConfirmPassword] = useState("")
  const [fullName, setFullName] = useState("")
  const [isLoading, setIsLoading] = useState(false)

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    setIsLoading(true)
    setTimeout(() => setIsLoading(false), 1500)
    if (isLogin) {
      console.log("Login:", { email, password })
    } else {
      console.log("Sign Up:", { fullName, email, password, confirmPassword })
    }
  }

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1,
        delayChildren: 0.2,
      },
    },
  }

  const itemVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: {
      opacity: 1,
      y: 0,
      transition: { duration: 0.5 },
    },
  }

  return (
    <div className="relative min-h-screen overflow-hidden flex items-center justify-center px-4 py-12">
      {/* Animated Background */}
      <motion.div
        className="absolute inset-0 bg-gradient-to-br from-slate-950 via-primary/5 to-slate-950"
        animate={{
          backgroundPosition: ["0% 0%", "100% 100%"],
        }}
        transition={{ duration: 8, repeat: Infinity, ease: "linear" }}
      />

      {/* Animated Gradient Orbs */}
      <motion.div
        className="absolute top-0 left-0 w-96 h-96 bg-gradient-to-br from-primary/20 to-accent/20 rounded-full blur-3xl"
        animate={{
          x: [0, 100, 0],
          y: [0, 50, 0],
        }}
        transition={{ duration: 10, repeat: Infinity }}
      />
      <motion.div
        className="absolute bottom-0 right-0 w-96 h-96 bg-gradient-to-tl from-accent/20 to-primary/10 rounded-full blur-3xl"
        animate={{
          x: [0, -100, 0],
          y: [0, -50, 0],
        }}
        transition={{ duration: 12, repeat: Infinity }}
      />

      {/* Floating particles */}
      <div className="absolute inset-0 overflow-hidden">
        {[...Array(20)].map((_, i) => (
          <motion.div
            key={i}
            className="absolute w-1 h-1 bg-primary/30 rounded-full"
            style={{
              left: `${Math.random() * 100}%`,
              top: `${Math.random() * 100}%`,
            }}
            animate={{
              y: [0, -100, 0],
              opacity: [0, 1, 0],
            }}
            transition={{
              duration: 3 + Math.random() * 3,
              repeat: Infinity,
              delay: Math.random() * 2,
            }}
          />
        ))}
      </div>

      {/* Content */}
      <motion.div
        className="w-full max-w-md relative z-10"
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ duration: 0.5 }}
      >
        {/* Back Button */}
        <motion.div
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ delay: 0.1 }}
          className="mb-8"
        >
          <Link
            href="/"
            className="flex items-center gap-2 text-muted-foreground hover:text-foreground transition-colors w-fit"
          >
            <ArrowLeft className="w-4 h-4" />
            <span className="text-sm font-medium">Orqaga qaytish</span>
          </Link>
        </motion.div>

        {/* Card */}
        <motion.div
          className="bg-gradient-to-br from-slate-900/40 to-slate-900/20 backdrop-blur-xl border border-primary/20 rounded-3xl p-8 shadow-2xl"
          variants={containerVariants}
          initial="hidden"
          animate="visible"
          whileHover={{ borderColor: "var(--primary)" }}
          transition={{ duration: 0.3 }}
        >
          {/* Toggle Buttons */}
          <motion.div variants={itemVariants} className="flex gap-3 mb-8">
            <motion.button
              onClick={() => setIsLogin(true)}
              className={`flex-1 py-2.5 px-4 rounded-xl font-semibold transition-all ${
                isLogin
                  ? "bg-gradient-to-r from-primary to-accent text-primary-foreground shadow-lg"
                  : "border border-slate-700 text-muted-foreground hover:text-foreground"
              }`}
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
            >
              Kirish
            </motion.button>
            <motion.button
              onClick={() => setIsLogin(false)}
              className={`flex-1 py-2.5 px-4 rounded-xl font-semibold transition-all ${
                !isLogin
                  ? "bg-gradient-to-r from-primary to-accent text-primary-foreground shadow-lg"
                  : "border border-slate-700 text-muted-foreground hover:text-foreground"
              }`}
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
            >
              Ro'yxatdan o'tish
            </motion.button>
          </motion.div>

          {/* Header */}
          <AnimatePresence mode="wait">
            <motion.div
              key={isLogin ? "login" : "signup"}
              variants={itemVariants}
              initial="hidden"
              animate="visible"
              exit="hidden"
              className="text-center mb-8"
            >
              <motion.div
                className="flex justify-center mb-6"
                animate={{ y: [0, -15, 0] }}
                transition={{ duration: 2, repeat: Infinity }}
              >
                <motion.div
                  className="w-20 h-20 rounded-full bg-gradient-to-br from-primary/40 to-accent/40 flex items-center justify-center shadow-xl"
                  animate={{ scale: [1, 1.05, 1] }}
                  transition={{ duration: 2, repeat: Infinity }}
                >
                  <User className="w-10 h-10 text-primary" />
                </motion.div>
              </motion.div>
              <motion.h1
                className="text-4xl font-bold bg-gradient-to-r from-primary via-accent to-primary bg-clip-text text-transparent"
                animate={{ opacity: [0.8, 1, 0.8] }}
                transition={{ duration: 2, repeat: Infinity }}
              >
                {isLogin ? "Kirish" : "Ro'yxatdan o'tish"}
              </motion.h1>
              <motion.p className="text-muted-foreground text-sm mt-3">
                {isLogin
                  ? "Akkauntingizga kiring va o'qishni boshlab yuboringiz"
                  : "Yangi akkaunt yaratib, o'qishni boshlang"}
              </motion.p>
            </motion.div>
          </AnimatePresence>

          {/* Form */}
          <AnimatePresence mode="wait">
            <form onSubmit={handleSubmit} className="space-y-5" key={isLogin ? "login-form" : "signup-form"}>
              {/* Full Name (only for Sign Up) */}
              {!isLogin && (
                <motion.div
                  variants={itemVariants}
                  initial="hidden"
                  animate="visible"
                  exit="hidden"
                >
                  <label className="block text-sm font-semibold text-foreground mb-2.5">
                    To'liq ismi
                  </label>
                  <div className="relative group">
                    <div className="absolute left-4 top-1/2 -translate-y-1/2 text-primary group-focus-within:text-accent transition-colors z-10">
                      <User className="w-5 h-5" />
                    </div>
                    <motion.input
                      type="text"
                      placeholder="Sizning ismingiz"
                      value={fullName}
                      onChange={(e) => setFullName(e.target.value)}
                      className="w-full pl-12 pr-4 py-3 bg-slate-800/50 border border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary/50 transition-all hover:border-slate-600 text-foreground placeholder:text-muted-foreground/50"
                      whileFocus={{ scale: 1.01 }}
                      required
                    />
                  </div>
                </motion.div>
              )}

              {/* Email Input */}
              <motion.div
                variants={itemVariants}
                initial="hidden"
                animate="visible"
              >
                <label className="block text-sm font-semibold text-foreground mb-2.5">
                  Email manzili
                </label>
                <div className="relative group">
                  <div className="absolute left-4 top-1/2 -translate-y-1/2 text-primary group-focus-within:text-accent transition-colors z-10">
                    <motion.div
                      animate={{ rotate: [0, 15, -15, 0] }}
                      transition={{ duration: 2, repeat: Infinity }}
                    >
                      <Mail className="w-5 h-5" />
                    </motion.div>
                  </div>
                  <motion.input
                    type="email"
                    placeholder="example@email.com"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    className="w-full pl-12 pr-4 py-3 bg-slate-800/50 border border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary/50 transition-all hover:border-slate-600 text-foreground placeholder:text-muted-foreground/50"
                    whileFocus={{ scale: 1.01 }}
                    required
                  />
                </div>
              </motion.div>

              {/* Password Input */}
              <motion.div
                variants={itemVariants}
                initial="hidden"
                animate="visible"
              >
                <label className="block text-sm font-semibold text-foreground mb-2.5">
                  Parol
                </label>
                <div className="relative group">
                  <div className="absolute left-4 top-1/2 -translate-y-1/2 text-primary group-focus-within:text-accent transition-colors z-10">
                    <motion.div
                      animate={{ scale: [1, 1.15, 1] }}
                      transition={{ duration: 2, repeat: Infinity }}
                    >
                      <Lock className="w-5 h-5" />
                    </motion.div>
                  </div>
                  <motion.input
                    type={showPassword ? "text" : "password"}
                    placeholder="••••••••"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="w-full pl-12 pr-12 py-3 bg-slate-800/50 border border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary/50 transition-all hover:border-slate-600 text-foreground placeholder:text-muted-foreground/50"
                    whileFocus={{ scale: 1.01 }}
                    required
                  />
                  <motion.button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-4 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors z-10"
                    whileHover={{ scale: 1.1 }}
                    whileTap={{ scale: 0.95 }}
                  >
                    {showPassword ? (
                      <Eye className="w-5 h-5" />
                    ) : (
                      <EyeOff className="w-5 h-5" />
                    )}
                  </motion.button>
                </div>
              </motion.div>

              {/* Confirm Password (only for Sign Up) */}
              {!isLogin && (
                <motion.div
                  variants={itemVariants}
                  initial="hidden"
                  animate="visible"
                  exit="hidden"
                >
                  <label className="block text-sm font-semibold text-foreground mb-2.5">
                    Parolni tasdiqlang
                  </label>
                  <div className="relative group">
                    <div className="absolute left-4 top-1/2 -translate-y-1/2 text-primary group-focus-within:text-accent transition-colors z-10">
                      <Lock className="w-5 h-5" />
                    </div>
                    <motion.input
                      type={showConfirmPassword ? "text" : "password"}
                      placeholder="••••••••"
                      value={confirmPassword}
                      onChange={(e) => setConfirmPassword(e.target.value)}
                      className="w-full pl-12 pr-12 py-3 bg-slate-800/50 border border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary/50 transition-all hover:border-slate-600 text-foreground placeholder:text-muted-foreground/50"
                      whileFocus={{ scale: 1.01 }}
                      required
                    />
                    <motion.button
                      type="button"
                      onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                      className="absolute right-4 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors z-10"
                      whileHover={{ scale: 1.1 }}
                      whileTap={{ scale: 0.95 }}
                    >
                      {showConfirmPassword ? (
                        <Eye className="w-5 h-5" />
                      ) : (
                        <EyeOff className="w-5 h-5" />
                      )}
                    </motion.button>
                  </div>
                </motion.div>
              )}

              {/* Remember & Forgot Password (only for Login) */}
              {isLogin && (
                <motion.div
                  variants={itemVariants}
                  className="flex items-center justify-between pt-2"
                >
                  <label className="flex items-center gap-2 cursor-pointer group">
                    <input
                      type="checkbox"
                      className="w-4 h-4 rounded border border-slate-700 bg-slate-800/50 checked:bg-gradient-to-r checked:from-primary checked:to-accent accent-primary transition-colors"
                    />
                    <span className="text-sm text-muted-foreground group-hover:text-foreground transition-colors">
                      Eslab qol
                    </span>
                  </label>
                  <Link
                    href="/forgot-password"
                    className="text-sm text-primary hover:text-accent transition-colors font-medium"
                  >
                    Parolni unitdingizmi?
                  </Link>
                </motion.div>
              )}

              {/* Submit Button */}
              <motion.div variants={itemVariants}>
                <motion.button
                  type="submit"
                  disabled={isLoading}
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                  className="w-full py-3 px-4 bg-gradient-to-r from-primary via-primary to-accent hover:from-primary/90 hover:to-accent/90 text-primary-foreground rounded-xl font-semibold transition-all shadow-lg hover:shadow-2xl disabled:opacity-50 disabled:cursor-not-allowed relative overflow-hidden"
                >
                  <motion.div
                    className="absolute inset-0 bg-gradient-to-r from-white/20 to-transparent"
                    animate={{ x: isLoading ? ["-100%", "100%"] : "-100%" }}
                    transition={{ duration: 1, repeat: isLoading ? Infinity : 0 }}
                  />
                  <span className="relative flex items-center justify-center gap-2">
                    {isLoading ? (
                      <>
                        <motion.div
                          animate={{ rotate: 360 }}
                          transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
                        >
                          <Sparkles className="w-4 h-4" />
                        </motion.div>
                        Yuklanmoqda...
                      </>
                    ) : isLogin ? (
                      "Kirish"
                    ) : (
                      "Ro'yxatdan o'tish"
                    )}
                  </span>
                </motion.button>
              </motion.div>
            </form>
          </AnimatePresence>
        </motion.div>
      </motion.div>
    </div>
  )
}
